// Adapter Shopify Blog — normalisasi kredensial user
// Auth: Admin API access token (shpat_…, custom app lama) ATAU Client ID + Client Secret (app Dev Dashboard, ditukar jadi token 24 jam)
const IN = $input.first().json;
const S = (IN.cms || {}).shopify || {};
let shop = String(S.shop || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, '');
if (shop && !shop.includes('.')) shop = shop + '.myshopify.com';
const accessToken = String(S.accessToken || '').trim();
const clientId = String(S.clientId || '').trim();
const clientSecret = String(S.clientSecret || '').trim();
let needsExchange = !accessToken && !!clientId && !!clientSecret;
let preError = '';
if (!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(shop)) preError = 'Domain toko harus berformat namatoko.myshopify.com (bukan domain custom).';
else if (!accessToken && !needsExchange) preError = 'Isi Admin API access token, atau Client ID + Client Secret.';
// jangan kirim rahasia ke host yang tidak valid
if (preError) needsExchange = false;
return [{ json: {
  cmsType: 'shopify', action: IN.action === 'publish' ? 'publish' : 'draft',
  shop, storeHandle: shop.replace(/\.myshopify\.com$/, ''), needsExchange, accessToken, clientId, clientSecret,
  blogId: String(S.blogId || '').trim(), authorName: String(S.authorName || IN.clientName || 'Admin').trim() || 'Admin',
  article: IN.article && typeof IN.article === 'object' ? IN.article : null,
  postId: String(IN.postId || '').trim(),
  preError, requestId: IN.requestId || '',
} }];

// Adapter Shopify — tentukan access token (langsung, atau hasil tukar Client Credentials)
const P = $('Siapkan Shopify').first().json;
let token = P.accessToken, preError = P.preError, tokenNote = '';
if (!preError && P.needsExchange) {
  const R = $('Shopify: Ambil Token').first().json || {};
  const st = Number(R.statusCode || 0);
  let b = R.body; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = { raw: b.slice(0, 200) }; } }
  b = b || {};
  if (st >= 200 && st < 300 && b.access_token) { token = b.access_token; tokenNote = 'client_credentials'; }
  else if (st === 404) preError = 'Toko ' + P.shop + ' tidak ditemukan (404), atau app belum di-install di toko ini. Cek domain .myshopify.com.';
  else preError = 'Gagal menukar Client ID/Secret jadi token (HTTP ' + (st || '-') + '): ' + (b.error_description || b.error || b.errors || b.raw || 'cek Client ID & Secret, dan pastikan app sudah di-install di toko ini (app & toko harus satu organisasi Shopify).');
}
if (preError) token = '';
return [{ json: Object.assign({}, P, { token, tokenNote, preError, accessToken: undefined, clientSecret: undefined,
  gqlUrl: 'https://' + (preError ? 'invalid-shop.myshopify.com' : P.shop) + '/admin/api/2026-07/graphql.json' }) }];

// Adapter Shopify — pilih blog, ubah markdown → HTML, susun mutation articleCreate / articleUpdate
const P = $('Shopify: Auth').first().json;
const R = $input.first().json || {};
// ===== Markdown mini-parser (dipakai adapter WordPress, Wix, Sanity, Shopify) =====
// Placeholder gambar Markimate: baris `![alt](markimate:image:N)` → html: <img data-markimate-idx=N>, portable text: {_type:'image', _markimateIdx:N} (diganti asset oleh adapter), ricos: dilewati.
// parseMarkdown(md) -> [{type:'heading',level,inlines}|{type:'paragraph',inlines}|{type:'list',ordered,items:[inlines]}|{type:'quote',inlines}]
// inlines: [{text, bold, italic, code, href}]
function parseInline(s) {
  const out = []; const src = String(s || '');
  const push = (t, m) => { if (t) out.push(Object.assign({ text: t }, m || {})); };
  const re = /(\*\*([^*]+)\*\*|__([^_]+)__|\*([^*\n]+)\*|_([^_\n]+)_|`([^`]+)`|\[([^\]]+)\]\(([^)\s]+)\))/g;
  let m; let last = 0;
  while ((m = re.exec(src))) {
    push(src.slice(last, m.index));
    if (m[2] || m[3]) push(m[2] || m[3], { bold: true });
    else if (m[4] || m[5]) push(m[4] || m[5], { italic: true });
    else if (m[6]) push(m[6], { code: true });
    else if (m[7]) push(m[7], { href: m[8] });
    last = m.index + m[0].length;
  }
  push(src.slice(last));
  return out;
}
function parseMarkdown(md) {
  const lines = String(md || '').replace(/\r/g, '').split('\n');
  const blocks = []; let para = []; let list = null;
  const flushPara = () => { if (para.length) { blocks.push({ type: 'paragraph', inlines: parseInline(para.join(' ')) }); para = []; } };
  const flushList = () => { if (list) { blocks.push(list); list = null; } };
  for (const raw of lines) {
    const t = raw.trim();
    if (!t) { flushPara(); flushList(); continue; }
    let m;
    if ((m = t.match(/^!\[([^\]]*)\]\(([^)\s]+)\)$/))) { flushPara(); flushList(); const pm = m[2].match(/^markimate:image:(\d+)$/); blocks.push({ type: 'image', alt: m[1], src: pm ? '' : m[2], idx: pm ? Number(pm[1]) : null }); continue; }
    if ((m = t.match(/^(#{1,6})\s+(.*)$/))) { flushPara(); flushList(); blocks.push({ type: 'heading', level: Math.min(Math.max(m[1].length, 2), 4), inlines: parseInline(m[2].replace(/\s#+$/, '')) }); continue; }
    if ((m = t.match(/^[-*+]\s+(.*)$/))) { flushPara(); if (!list || list.ordered) { flushList(); list = { type: 'list', ordered: false, items: [] }; } list.items.push(parseInline(m[1])); continue; }
    if ((m = t.match(/^\d+[.)]\s+(.*)$/))) { flushPara(); if (!list || !list.ordered) { flushList(); list = { type: 'list', ordered: true, items: [] }; } list.items.push(parseInline(m[1])); continue; }
    if ((m = t.match(/^>\s?(.*)$/))) { flushPara(); flushList(); blocks.push({ type: 'quote', inlines: parseInline(m[1]) }); continue; }
    if (/^(-{3,}|\*{3,})$/.test(t)) { flushPara(); flushList(); continue; }
    flushList(); para.push(t);
  }
  flushPara(); flushList();
  return blocks;
}
const escHtml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function inlinesToHtml(inl) {
  return inl.map(x => { let h = escHtml(x.text); if (x.code) h = '<code>' + h + '</code>'; if (x.bold) h = '<strong>' + h + '</strong>'; if (x.italic) h = '<em>' + h + '</em>'; if (x.href) h = '<a href="' + escHtml(x.href) + '" target="_blank" rel="noopener">' + h + '</a>'; return h; }).join('');
}
function markdownToHtml(md) {
  return parseMarkdown(md).map(b => {
    if (b.type === 'heading') return '<h' + b.level + '>' + inlinesToHtml(b.inlines) + '</h' + b.level + '>';
    if (b.type === 'image') return b.idx !== null ? '<img data-markimate-idx="' + b.idx + '" alt="' + escHtml(b.alt) + '">' : '<figure><img src="' + escHtml(b.src) + '" alt="' + escHtml(b.alt) + '"></figure>';
    if (b.type === 'quote') return '<blockquote><p>' + inlinesToHtml(b.inlines) + '</p></blockquote>';
    if (b.type === 'list') return (b.ordered ? '<ol>' : '<ul>') + b.items.map(it => '<li>' + inlinesToHtml(it) + '</li>').join('') + (b.ordered ? '</ol>' : '</ul>');
    return '<p>' + inlinesToHtml(b.inlines) + '</p>';
  }).join('\n');
}
// Ricos (Wix rich content)
function markdownToRicos(md) {
  let seq = 0; const nid = () => 'n' + (++seq).toString(36) + Date.now().toString(36).slice(-4);
  const textNode = x => { const dec = []; if (x.bold) dec.push({ type: 'BOLD', fontWeightValue: 700 }); if (x.italic) dec.push({ type: 'ITALIC', italicData: true }); if (x.href) dec.push({ type: 'LINK', linkData: { link: { url: x.href, target: 'BLANK' } } }); return { type: 'TEXT', id: '', nodes: [], textData: { text: x.text, decorations: dec } }; };
  const paragraph = inl => ({ type: 'PARAGRAPH', id: nid(), nodes: inl.map(textNode), paragraphData: {} });
  const nodes = [];
  for (const b of parseMarkdown(md)) {
    if (b.type === 'image') continue; // gambar belum didukung di Wix (lihat warnings)
    if (b.type === 'heading') nodes.push({ type: 'HEADING', id: nid(), nodes: b.inlines.map(textNode), headingData: { level: b.level } });
    else if (b.type === 'quote') nodes.push({ type: 'BLOCKQUOTE', id: nid(), nodes: [paragraph(b.inlines)], blockquoteData: {} });
    else if (b.type === 'list') nodes.push({ type: b.ordered ? 'ORDERED_LIST' : 'BULLETED_LIST', id: nid(), nodes: b.items.map(it => ({ type: 'LIST_ITEM', id: nid(), nodes: [paragraph(it)] })), [b.ordered ? 'orderedListData' : 'bulletedListData']: { indentation: 0 } });
    else nodes.push(paragraph(b.inlines));
  }
  return { nodes, metadata: { version: 1 } };
}
// Portable Text (Sanity block content)
function markdownToPortableText(md) {
  let seq = 0; const key = () => 'k' + (++seq).toString(36) + Math.random().toString(36).slice(2, 8);
  const block = (inl, extra) => {
    const markDefs = [];
    const children = (inl.length ? inl : [{ text: '' }]).map(x => {
      const marks = [];
      if (x.bold) marks.push('strong'); if (x.italic) marks.push('em'); if (x.code) marks.push('code');
      if (x.href) { const k = key(); markDefs.push({ _key: k, _type: 'link', href: x.href }); marks.push(k); }
      return { _type: 'span', _key: key(), text: x.text, marks };
    });
    return Object.assign({ _type: 'block', _key: key(), style: 'normal', markDefs, children }, extra || {});
  };
  const out = [];
  for (const b of parseMarkdown(md)) {
    if (b.type === 'image') { if (b.idx !== null) out.push({ _type: 'image', _key: key(), _markimateIdx: b.idx, alt: b.alt }); continue; }
    if (b.type === 'heading') out.push(block(b.inlines, { style: 'h' + b.level }));
    else if (b.type === 'quote') out.push(block(b.inlines, { style: 'blockquote' }));
    else if (b.type === 'list') for (const it of b.items) out.push(block(it, { listItem: b.ordered ? 'number' : 'bullet', level: 1 }));
    else out.push(block(b.inlines));
  }
  return out;
}

let preError = P.preError;
let blogs = [], primaryUrl = '';
if (!preError) {
  const st = Number(R.statusCode || 0);
  let b = R.body; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
  b = b || {};
  if (st === 401) preError = 'Token Shopify tidak valid (401). Cek access token / Client ID & Secret.';
  else if (st === 403) preError = 'Token Shopify tidak punya izin (403). Aktifkan scope write_content (dan read_content) lalu install ulang app.';
  else if (st === 404) preError = 'Toko Shopify tidak ditemukan (404). Cek domain .myshopify.com.';
  else if (!(st >= 200 && st < 300) || !b.data) preError = 'Gagal membaca toko Shopify: ' + (b.errors ? JSON.stringify(b.errors).slice(0, 200) : 'HTTP ' + st);
  else { blogs = (b.data.blogs && b.data.blogs.nodes) || []; primaryUrl = ((b.data.shop || {}).primaryDomain || {}).url || ''; }
}
const A = P.article; const publish = P.action === 'publish';
let blog = null;
if (!preError) {
  blog = P.blogId ? blogs.find(x => x.id === P.blogId || x.id.endsWith('/' + P.blogId) || x.handle === P.blogId) : blogs[0];
  if (!blog && !P.postId) preError = P.blogId ? 'Blog "' + P.blogId + '" tidak ditemukan di toko.' : 'Toko belum punya blog. Buat dulu di Shopify Admin → Online Store → Blog posts → Manage blogs.';
}
const articleGid = P.postId ? (P.postId.startsWith('gid://') ? P.postId : 'gid://shopify/Article/' + P.postId) : '';
const FIELDS = 'article { id handle title isPublished blog { handle } } userErrors { field message }';
let query, variables;
if (A && A.title) {
  const input = {
    title: String(A.title),
    handle: String(A.slug || '').trim() || undefined,
    body: markdownToHtml(A.bodyMarkdown || A.body || ''),
    summary: A.excerpt ? '<p>' + String(A.excerpt).replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</p>' : undefined,
    tags: Array.isArray(A.keywords) ? A.keywords.slice(0, 8).map(String) : undefined,
    isPublished: publish,
  };
  if (publish) input.publishDate = new Date().toISOString();
  if (articleGid) { query = 'mutation($id: ID!, $article: ArticleUpdateInput!) { articleUpdate(id: $id, article: $article) { ' + FIELDS + ' } }'; variables = { id: articleGid, article: input }; }
  else { input.blogId = blog && blog.id; input.author = { name: P.authorName }; query = 'mutation($article: ArticleCreateInput!) { articleCreate(article: $article) { ' + FIELDS + ' } }'; variables = { article: input }; }
} else if (articleGid) {
  query = 'mutation($id: ID!, $article: ArticleUpdateInput!) { articleUpdate(id: $id, article: $article) { ' + FIELDS + ' } }';
  variables = { id: articleGid, article: { isPublished: true, publishDate: new Date().toISOString() } };
} else preError = preError || 'Tidak ada artikel maupun postId untuk diproses.';
return [{ json: { gqlUrl: P.gqlUrl, token: P.token, body: { query: query || '{ shop { name } }', variables: variables || {} },
  preError, shop: P.shop, storeHandle: P.storeHandle, primaryUrl, blogHandle: blog ? blog.handle : '',
  action: P.action, title: A ? A.title || '' : '', requestId: P.requestId } }];

// Adapter Shopify — rapikan hasil mutation jadi format standar Supermat
const P = $('Susun Artikel Shopify').first().json;
const fail = (msg, st) => [{ json: { status: 'error', cmsType: 'shopify', action: P.action, httpStatus: st || 400, message: msg, requestId: P.requestId } }];
if (P.preError) return fail(P.preError, 400);
const R = $input.first().json || {};
const st = Number(R.statusCode || 0);
let b = R.body; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = { raw: b.slice(0, 200) }; } }
b = b || {};
if (st === 401 || st === 403) return fail('Shopify menolak akses (' + st + '). Pastikan app punya scope write_content.', st);
if (!(st >= 200 && st < 300)) return fail('Shopify error HTTP ' + (st || '-') + ': ' + (b.errors ? JSON.stringify(b.errors).slice(0, 200) : b.raw || ''), st || 502);
if (b.errors && !b.data) return fail('GraphQL Shopify error: ' + JSON.stringify(b.errors).slice(0, 300), 400);
const payload = (b.data && (b.data.articleCreate || b.data.articleUpdate)) || {};
const ue = payload.userErrors || [];
if (ue.length) return fail('Shopify menolak artikel: ' + ue.map(e => (e.field ? e.field.join('.') + ': ' : '') + e.message).join('; '), 400);
const a = payload.article;
if (!a || !a.id) return fail('Respons Shopify tanpa artikel.', 502);
const num = String(a.id).split('/').pop();
const blogHandle = (a.blog && a.blog.handle) || P.blogHandle;
const base = (P.primaryUrl || ('https://' + P.shop)).replace(/\/+$/, '');
return [{ json: {
  status: 'ok', cmsType: 'shopify', action: P.action,
  postId: num, postStatus: a.isPublished ? 'publish' : 'draft',
  draftEditUrl: 'https://admin.shopify.com/store/' + P.storeHandle + '/content/articles/' + num,
  publicUrl: a.isPublished ? base + '/blogs/' + blogHandle + '/' + a.handle : '',
  previewUrl: '', title: a.title || P.title,
  message: a.isPublished ? 'Artikel terbit di blog Shopify.' : 'Draf (tersembunyi) tersimpan di blog Shopify.',
  requestId: P.requestId,
} }];
